svg.script:
(() => {
  const icon = document.currentScript && document.currentScript.ownerSVGElement;
  if (!icon) return;

  const toggle = () => {
    const collapsed = icon.classList.toggle("is-collapsed");
    icon.setAttribute("aria-pressed", String(collapsed));
    icon.dispatchEvent(new CustomEvent("paneltoggle", {
      bubbles: true,
      detail: { collapsed }
    }));
  };

  icon.addEventListener("click", toggle);
  icon.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    event.preventDefault();
    toggle();
  });
})();
